using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApproved95()
    {
        // No checkout API exists yet, so the outcome can only be asserted by looking for one.
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(type => type.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase));

        Assert.NotEmpty(checkoutTypes);
    }
}
